spec.rawSql:
select count(*)::bigint as value
from music.scrobble_events
where $__timeFilter(scrobbled_at);

select count(distinct track_id)::bigint as value
from music.scrobbles
where $__timeFilter(scrobbled_at);

select count(distinct artist_id)::bigint as value
from music.scrobbles
where $__timeFilter(scrobbled_at);
